class Solution:
    def pathSum(self, root, targetSum):
        counts={0:1}
        def walk(node,total):
            if not node:return 0
            total+=node.val
            result=counts.get(total-targetSum,0)
            counts[total]=counts.get(total,0)+1
            result+=walk(node.left,total)+walk(node.right,total)
            counts[total]-=1
            return result
        return walk(root,0)
